--
-- Table structure for table `classes`
--

DROP TABLE IF EXISTS `classes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `classes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `school_id` int NOT NULL,
  `class_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `section` enum('A','B','C','D','E','F') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A',
  `stream` enum('Science','Commerce','Arts','General') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'General',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `max_students` int DEFAULT '50',
  `current_students` int DEFAULT '0',
  `medium` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'English',
  `academic_year` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2026-2027',
  `display_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`class_name` in (_utf8mb4'Nursery',_utf8mb4'LKG',_utf8mb4'UKG')) then concat(`class_name`,_utf8mb4'-',`section`,_utf8mb4' (',`medium`,_utf8mb4')') else concat(_utf8mb4'Std ',`class_name`,_utf8mb4'-',`section`,_utf8mb4' (',`medium`,_utf8mb4')') end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_class_details` (`school_id`,`class_name`,`section`,`stream`,`medium`,`academic_year`),
  KEY `idx_school_id` (`school_id`),
  CONSTRAINT `classes_ibfk_1` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=308 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
