DROP TABLE IF EXISTS `permission_role`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `permission_role` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'Primary Key',
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'UUID for external references',
  `permission_id` bigint unsigned NOT NULL COMMENT 'Reference to permissions table',
  `role_id` bigint unsigned NOT NULL COMMENT 'Reference to roles table',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Admin remarks',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1=active, 0=inactive',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Timestamp of assignment',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Timestamp of assignment update',
  `created_by` bigint unsigned DEFAULT NULL COMMENT 'User ID who assigned',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT 'User ID who last updated assignment',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT 'Timestamp of soft delete',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  KEY `idx_perm_role_perm_id` (`permission_id`),
  KEY `idx_perm_role_role_id` (`role_id`),
  KEY `idx_perm_role_status` (`status`),
  KEY `idx_perm_role_created_at` (`created_at`),
  KEY `idx_perm_role_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_perm_role_perm_id` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_perm_role_role_id` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Junction table for permission-role mapping';
