--
-- Table structure for table `student_transport_allocations`
--

DROP TABLE IF EXISTS `student_transport_allocations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_transport_allocations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `school_id` int NOT NULL,
  `student_id` int NOT NULL,
  `route_id` int unsigned NOT NULL,
  `stop_id` int unsigned DEFAULT NULL,
  `pickup_stop_id` int unsigned DEFAULT NULL,
  `drop_stop_id` int unsigned DEFAULT NULL,
  `pickup_required` tinyint(1) NOT NULL DEFAULT '1',
  `drop_required` tinyint(1) NOT NULL DEFAULT '1',
  `fee_plan_id` int unsigned DEFAULT NULL,
  `allocation_start_date` date DEFAULT NULL,
  `allocation_end_date` date DEFAULT NULL,
  `status` enum('active','inactive','paused') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `pickup_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pickup_latitude` decimal(10,7) DEFAULT NULL,
  `pickup_longitude` decimal(10,7) DEFAULT NULL,
  `drop_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drop_latitude` decimal(10,7) DEFAULT NULL,
  `drop_longitude` decimal(10,7) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_student_active_transport` (`school_id`,`student_id`,`status`),
  KEY `idx_sta_school_student` (`school_id`,`student_id`),
  KEY `idx_sta_route` (`route_id`),
  KEY `idx_sta_pickup_stop` (`pickup_stop_id`),
  KEY `idx_sta_drop_stop` (`drop_stop_id`),
  KEY `idx_sta_fee_plan` (`fee_plan_id`)
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

